import React, { useState, useEffect } from 'react';
import { paymentService } from '../services/paymentService';
import { authService } from '../services/authService';

function AdminPanel({ onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [referrals, setReferrals] = useState([]);
  const [feedbacks, setFeedbacks] = useState([]);
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalTransactions: 0,
    totalRevenue: 0,
    totalReferrals: 0,
    totalFeedbacks: 0
  });
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    const usersData = JSON.parse(localStorage.getItem('users') || '[]');
    const transactionsData = paymentService.getTransactions();
    const referralsData = JSON.parse(localStorage.getItem('referrals') || '[]');
    const feedbacksData = JSON.parse(localStorage.getItem('feedbacks') || '[]');
    
    setUsers(usersData);
    setTransactions(transactionsData);
    setReferrals(referralsData);
    setFeedbacks(feedbacksData);
    
    const totalRevenue = transactionsData
      .filter(t => t.type === 'پرداخت')
      .reduce((sum, t) => sum + t.amount, 0);
    
    setStats({
      totalUsers: usersData.length,
      totalTransactions: transactionsData.length,
      totalRevenue: totalRevenue,
      totalReferrals: referralsData.length,
      totalFeedbacks: feedbacksData.length
    });
  };

  const deleteUser = (userId) => {
    if (window.confirm('آیا از حذف این کاربر مطمئن هستید؟')) {
      const updated = users.filter(u => u.id !== userId);
      setUsers(updated);
      localStorage.setItem('users', JSON.stringify(updated));
      loadData();
    }
  };

  const filteredTransactions = transactions.filter(t => 
    t.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    t.type?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const tabs = [
    { id: 'dashboard', label: '📊 داشبورد' },
    { id: 'users', label: '👥 کاربران' },
    { id: 'transactions', label: '💰 تراکنش‌ها' },
    { id: 'referrals', label: '🔗 دعوت‌ها' },
    { id: 'feedbacks', label: '💬 بازخوردها' },
    { id: 'settings', label: '⚙️ تنظیمات' }
  ];

  const renderTab = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="glass-card text-center">
              <div className="text-3xl mb-2">👥</div>
              <div className="text-2xl font-bold text-blue-600">{stats.totalUsers}</div>
              <div className="text-sm text-gray-500">کاربران کل</div>
            </div>
            <div className="glass-card text-center">
              <div className="text-3xl mb-2">💰</div>
              <div className="text-2xl font-bold text-green-600">{stats.totalRevenue.toFixed(2)} TON</div>
              <div className="text-sm text-gray-500">درآمد کل</div>
            </div>
            <div className="glass-card text-center">
              <div className="text-3xl mb-2">📊</div>
              <div className="text-2xl font-bold text-purple-600">{stats.totalTransactions}</div>
              <div className="text-sm text-gray-500">تراکنش‌ها</div>
            </div>
            <div className="glass-card text-center">
              <div className="text-3xl mb-2">🔗</div>
              <div className="text-2xl font-bold text-orange-600">{stats.totalReferrals}</div>
              <div className="text-sm text-gray-500">دعوت‌ها</div>
            </div>
          </div>
        );

      case 'users':
        return (
          <div className="glass-card">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-gray-800">👥 لیست کاربران</h3>
              <span className="text-sm text-gray-500">{users.length} کاربر</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-200">
                    <th className="text-right p-3 text-gray-600">#</th>
                    <th className="text-right p-3 text-gray-600">نام کاربری</th>
                    <th className="text-right p-3 text-gray-600">سطح</th>
                    <th className="text-right p-3 text-gray-600">VIP</th>
                    <th className="text-right p-3 text-gray-600">تاریخ ثبت</th>
                    <th className="text-right p-3 text-gray-600">عملیات</th>
                  </tr>
                </thead>
                <tbody>
                  {users.length === 0 ? (
                    <tr><td colSpan="6" className="text-center p-4 text-gray-400">هیچ کاربری ثبت نشده</td></tr>
                  ) : (
                    users.map((user, index) => (
                      <tr key={user.id} className="border-b border-gray-100 hover:bg-blue-50/50 transition-colors">
                        <td className="p-3 text-gray-600">{index + 1}</td>
                        <td className="p-3 font-medium text-gray-800">{user.username || 'کاربر'}</td>
                        <td className="p-3"><span className="px-2 py-1 bg-blue-100 text-blue-600 rounded-full text-xs">Level {user.level || 1}</span></td>
                        <td className="p-3"><span className="px-2 py-1 bg-yellow-100 text-yellow-600 rounded-full text-xs">VIP {user.vip || 0}</span></td>
                        <td className="p-3 text-gray-500">{new Date(user.createdAt).toLocaleDateString('fa-IR')}</td>
                        <td className="p-3">
                          <button 
                            onClick={() => deleteUser(user.id)}
                            className="px-3 py-1 bg-red-50 text-red-500 rounded-lg text-xs hover:bg-red-100 transition-colors"
                          >
                            حذف
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'transactions':
        return (
          <div className="glass-card">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-gray-800">💰 لیست تراکنش‌ها</h3>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="جستجو..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="px-3 py-1 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-200">
                    <th className="text-right p-3 text-gray-600">#</th>
                    <th className="text-right p-3 text-gray-600">نوع</th>
                    <th className="text-right p-3 text-gray-600">مبلغ</th>
                    <th className="text-right p-3 text-gray-600">توضیحات</th>
                    <th className="text-right p-3 text-gray-600">تاریخ</th>
                    <th className="text-right p-3 text-gray-600">وضعیت</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredTransactions.length === 0 ? (
                    <tr><td colSpan="6" className="text-center p-4 text-gray-400">هیچ تراکنشی ثبت نشده</td></tr>
                  ) : (
                    filteredTransactions.map((tx, index) => (
                      <tr key={tx.id} className="border-b border-gray-100 hover:bg-blue-50/50 transition-colors">
                        <td className="p-3 text-gray-600">{index + 1}</td>
                        <td className="p-3">
                          <span className={`px-2 py-1 rounded-full text-xs ${tx.type === 'پرداخت' ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                            {tx.type}
                          </span>
                        </td>
                        <td className="p-3 font-bold text-gray-800">{tx.amount} TON</td>
                        <td className="p-3 text-gray-600">{tx.description || '-'}</td>
                        <td className="p-3 text-gray-500">{tx.date}</td>
                        <td className="p-3">
                          <span className="px-2 py-1 bg-green-100 text-green-600 rounded-full text-xs">موفق</span>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'referrals':
        return (
          <div className="glass-card">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-gray-800">🔗 لیست دعوت‌ها</h3>
              <span className="text-sm text-gray-500">{referrals.length} دعوت</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-200">
                    <th className="text-right p-3 text-gray-600">#</th>
                    <th className="text-right p-3 text-gray-600">کاربر دعوت‌کننده</th>
                    <th className="text-right p-3 text-gray-600">کاربر دعوت‌شده</th>
                    <th className="text-right p-3 text-gray-600">پاداش</th>
                    <th className="text-right p-3 text-gray-600">تاریخ</th>
                  </tr>
                </thead>
                <tbody>
                  {referrals.length === 0 ? (
                    <tr><td colSpan="5" className="text-center p-4 text-gray-400">هیچ دعوتی ثبت نشده</td></tr>
                  ) : (
                    referrals.map((ref, index) => (
                      <tr key={index} className="border-b border-gray-100 hover:bg-blue-50/50 transition-colors">
                        <td className="p-3 text-gray-600">{index + 1}</td>
                        <td className="p-3 font-medium text-gray-800">{ref.inviter || 'نامشخص'}</td>
                        <td className="p-3 text-gray-600">{ref.invited || 'نامشخص'}</td>
                        <td className="p-3 text-green-600 font-bold">+{ref.reward || 1} TON</td>
                        <td className="p-3 text-gray-500">{ref.date}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'feedbacks':
        return (
          <div className="glass-card">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-gray-800">💬 بازخوردهای کاربران</h3>
              <span className="text-sm text-gray-500">{feedbacks.length} بازخورد</span>
            </div>
            <div className="space-y-3 max-h-80 overflow-y-auto">
              {feedbacks.length === 0 ? (
                <p className="text-center p-4 text-gray-400">هیچ بازخوردی ثبت نشده</p>
              ) : (
                feedbacks.map((fb, index) => (
                  <div key={index} className="p-4 bg-gray-50 rounded-xl border border-gray-200">
                    <p className="text-gray-700 whitespace-pre-wrap">{fb.message}</p>
                    <div className="flex items-center justify-between mt-2">
                      <span className="text-xs text-gray-400">
                        {new Date(fb.date).toLocaleString('fa-IR')}
                      </span>
                      <button 
                        onClick={() => {
                          const updated = feedbacks.filter((_, i) => i !== index);
                          localStorage.setItem('feedbacks', JSON.stringify(updated));
                          loadData();
                        }}
                        className="px-2 py-1 bg-red-50 text-red-500 rounded-lg text-xs hover:bg-red-100 transition-colors"
                      >
                        حذف
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        );

      case 'settings':
        return (
          <div className="glass-card">
            <h3 className="font-bold text-gray-800 mb-4">⚙️ تنظیمات ادمین</h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                <div>
                  <p className="font-medium text-gray-800">آدرس کیف پول ادمین</p>
                  <p className="text-sm text-gray-500 font-mono break-all">UQCP4kR905Frt-W0HWjqZn4t2vvpz4t3uFYKI0b9JkUPZajI</p>
                </div>
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText('UQCP4kR905Frt-W0HWjqZn4t2vvpz4t3uFYKI0b9JkUPZajI');
                    alert('✅ کپی شد!');
                  }}
                  className="px-3 py-1 bg-blue-50 text-blue-600 rounded-lg text-sm hover:bg-blue-100 transition-colors"
                >
                  کپی
                </button>
              </div>
              <div className="p-3 bg-gray-50 rounded-xl">
                <p className="font-medium text-gray-800">کل کاربران</p>
                <p className="text-2xl font-bold text-blue-600">{stats.totalUsers}</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-xl">
                <p className="font-medium text-gray-800">درآمد کل</p>
                <p className="text-2xl font-bold text-green-600">{stats.totalRevenue.toFixed(2)} TON</p>
              </div>
              <button 
                onClick={() => {
                  if (window.confirm('⚠️ آیا از پاک کردن همه داده‌ها مطمئن هستید؟')) {
                    localStorage.clear();
                    alert('✅ همه داده‌ها پاک شد!');
                    loadData();
                  }
                }}
                className="w-full py-3 bg-red-50 text-red-500 rounded-xl font-bold hover:bg-red-100 transition-colors"
              >
                🗑️ پاک کردن همه داده‌ها
              </button>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50/50 p-4">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">🛠️ پنل مدیریت</h1>
            <p className="text-sm text-gray-500">خوش آمدید {localStorage.getItem('adminUsername')} 👋</p>
          </div>
          <button 
            onClick={onLogout}
            className="px-4 py-2 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 transition-colors text-sm font-medium"
          >
            🚪 خروج
          </button>
        </div>

        <div className="flex gap-2 mb-6 overflow-x-auto">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2 rounded-xl transition-all whitespace-nowrap ${
                activeTab === tab.id
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30'
                  : 'bg-white text-gray-600 hover:bg-gray-100'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {renderTab()}
      </div>
    </div>
  );
}

export default AdminPanel;
